/* ЯПОНСКИЕ КРОССВОРДЫ (нонограммы) на клетках листа.
   Числа слева от строки и над столбцом — длины закрашенных блоков по порядку;
   между блоками хотя бы одна пустая клетка. Щелчок по клетке закрашивает её
   (или ставит крестик — «здесь пусто»), решённая строка гасит свои числа.
   Все картинки проверены решателем: решение единственное и находится логикой,
   без угадывания. «Подсказка» не просто открывает клетку, а объясняет, из какой
   строки и почему она следует. Свой рисунок превращается в задачу кнопкой. */

/* ===== Поле на клетках листа: общий кусок игр магазина =====
   Строки и столбцы здесь — С НУЛЯ (r, c); адреса A1 считаются отсюда же.
   ячейка(строка, столбец) API плагина считает с единицы — поэтому везде «+ 1». */
const БУКВА = c => { let s = '', n = c + 1; while(n > 0){ const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = (n - 1 - m) / 26; } return s; };
const АДРЕС = (r, c) => БУКВА(c) + (r + 1);
const ОБЛАСТЬ = (r1, c1, r2, c2) => АДРЕС(r1, c1) + ':' + АДРЕС(r2, c2);
const клетка = (r, c) => ячейка(r + 1, c + 1);
/* Квадратные клетки: ширина столбца в знаках (знак — 7 точек), высота строки в пунктах (×4/3 точки). */
function клеткиКвадратом(r1, c1, r2, c2, точек){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(точек / 7);
  о.SetRowHeight(точек * 0.75);
}
/* Вернуть области обычные размеры клеток (столбец 92 точки, строка 24 точки = 18 пунктов). */
function обычныеРазмеры(r1, c1, r2, c2){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(92 / 7);
  о.SetRowHeight(18);
}
/* Ширина одного столбца и высота одной строки в точках экрана. */
function ширинаСтолбца(c, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c)).SetColumnWidth(точек / 7); }
function высотаСтроки(r, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r, 0, r, 0)).SetRowHeight(точек * 0.75); }
/* Приложение запоминает смещения строк и не сбрасывает их, когда плагин меняет высоты строк:
   после этого щелчок мыши попадает не в ту клетку. Пустая запись в далёкую пустую строку
   растит сетку листа, и смещения пересчитываются. Звать после смены высот. */
async function обновитьВысоты(){
  /* каждый раз — строка дальше прежней: сетка растёт, только если запись за её краем */
  let n = 0; try { n = +лист().память('высоты-шаг') || 0; } catch(e){}
  for(let k = n + 1; k <= n + 40; k++){
    const r = 5999 + k;
    let v = null;
    try { v = await клетка(r, 0).прочитать(); } catch(e){ continue; }
    if(v === null || v === undefined || v === ''){
      клетка(r, 0).значение = null;
      try { лист().запомнить('высоты-шаг', k); } catch(e){}
      return true;
    }
  }
  return false;
}
/* Курсор — на «стоянку» рядом с полем. Тогда повторный щелчок по той же клетке
   снова сменит выделение, и плагин получит событие: иначе второй щелчок молчал бы. */
function наСтоянку(r, c){ клетка(r, c).выделить(); }
/* Пуста ли область листа: игра не должна молча затирать чужие данные. */
async function областьПуста(r1, c1, r2, c2){
  const строки = await диапазон(ОБЛАСТЬ(r1, c1, r2, c2)).прочитать();
  for(const ряд of строки || []) for(const v of ряд || []) if(v !== null && v !== undefined && v !== '') return false;
  return true;
}
/* Рамка: все четыре стороны одним видом. */
const РАМКА = (вид, цвет) => ({в: {вид, цвет}, н: {вид, цвет}, л: {вид, цвет}, п: {вид, цвет}});
/* Число со словом в нужной форме: число(5, 'выстрел', 'выстрела', 'выстрелов') → «5 выстрелов». */
function число(n, одна, две, пять){ const a = Math.abs(n) % 100, b = a % 10;
  return n + ' ' + (a > 10 && a < 20 ? пять : b === 1 ? одна : b >= 2 && b <= 4 ? две : пять); }
/* Время «м:сс». */
const ВРЕМЯ = с => Math.floor(с / 60) + ':' + String(Math.floor(с % 60)).padStart(2, '0');
/* Повод события — клетка с нуля и на нужном ли листе. */
function гдеЩелчок(п, лист){
  if(!п || !п.адрес || (лист && п.лист !== лист)) return null;
  if(п.клеток > 1) return null;                     /* протянули мышью область — это не ход */
  return {r: п.строка - 1, c: п.столбец - 1};
}
/* Защита от «правой кнопки»: правый щелчок сначала зовёт меню, а через 150 мс
   приходит выделение той же клетки. Такой выбор ходом не считаем. */
let последнееМеню = {адрес: '', t: 0};
const этоПослеМеню = п => п && п.адрес === последнееМеню.адрес && Date.now() - последнееМеню.t < 1500;
/* ===== конец общего куска ===== */
/* Оформление области по клеткам. Api GetRange(…).SetNumberFormat и другие оформления области из потока
   задевают только ту часть, что была занята при запуске потока, — свежие строки остаются без оформления.
   л — лист плагина: лист(имя) или черновик; строки и столбцы — с нуля. */
function оформитьОбласть(л, r1, c1, r2, c2, стиль){
  if((r2 - r1 + 1) * (c2 - c1 + 1) > 300000) return false;
  for(let r = r1; r <= r2; r++) for(let c = c1; c <= c2; c++) л.ячейка(r + 1, c + 1).стиль = стиль;
  return true;
}
/* Картинки японских кроссвордов — свои рисунки; каждая проверена решателем по строкам:
   решение единственное и находится без перебора. */
const КАРТИНКИ = [["Сердце", "Разминка", ".#.#./#####/#####/.###./..#.."], ["Домик", "Разминка", "..#../.###./#####/#.#.#/#####"], ["Стрелка", "Разминка", "..#../.###./#.#.#/..#../..#.."], ["Ёлка", "10×10", "....##..../...####.../....##..../...####.../..######../...####.../.########./##########/....##..../...####..."], ["Чашка", "10×10", "..#..#..../...#..#.../..#..#..../........../#######.../#.....####/#.....#..#/#.....####/.#...#..../##########"], ["Ключ", "10×10", ".####...../##..##..../#....#..../##..##..../.####...../..##....../..##....../..####..../..##....../..####...."], ["Гриб", "10×10", "...####.../.##.##.##./#.######.#/##########/#.##..##.#/...#..#.../...#..#.../...#..#.../..##..##../..######.."], ["Рыба", "10×10", "........../....###.../#..#####../##########/.######.##/.#########/##########/#..#####../....###.../.........."], ["Ракета", "10×10", "....##..../...####.../...#..#.../...#..#.../...####.../...####.../..######../.##.##.##./#...##...#/....##...."], ["Зонт", "10×10", "....##..../..######../.########./##########/#.#.##.#.#/....##..../....##..../....##..../.#..##..../..###....."], ["Лодка", "10×10", "....#...../....##..../....###.../....####../....#####./....#...../##########/.########./..######../.........."], ["Кот", "10×10", "#......#../##....##../########../#.####.#../########../###..###.#/.######..#/..####...#/.######.##/########.."], ["Самолёт", "10×10", "....##..../....##..../...####.../.########./##########/....##..../....##..../...####.../..######../....##...."], ["Бабочка", "10×10", "##......##/###....###/####..####/####.#####/.###.####./..######../.###.####./####.#####/###.#..###/.#......#."], ["Якорь", "10×10", "....##..../...#..#.../....##..../..######../....##..../....##..../##..##..##/##..##..##/.########./...####..."], ["Звезда", "10×10", "....##..../....##..../...####.../##########/.########./..######../..######../.###..###./.##....##./##......##"], ["Сова", "15×15", "..##.......##../..###.....###../..#########..../.###########.../.##...###...##./.#.##.###.##.#./.##...###...##./.######.######./..####...####../..###########../..##.#####.##../..#.#######.#../..###########../...#########.../....##...##...."], ["Маяк", "15×15", "......###....../.....#####...../###..#...#..###/.....#####...../......###....../......###....../.....#####...../.....##.##...../.....#####...../....#######..../....###.###..../....#######..../...#########.../.#############./###############"], ["Кит", "15×15", "...#.#........./....#........../...###........./.............../...########..../..###########../.#############./##.##########.#/#############.#/#############.#/.###########.##/..#########.###/....######..#.#/.............../###############"], ["Заяц", "15×15", "....##...##..../...#..#.#..#.../...#..#.#..#.../...#..#.#..#.../....#.#.#.#..../....#######..../...#########.../..##.#####.##../..###########../..#####.#####../...####.####.../....#######..../...#########.../..###########../..####...####.."]];

const Р0 = 2, С0 = 1;                 /* подсказки и поле — с B3 */
const СТОЯНКА = {r: 1, c: 0};        /* A2 */
const ПАМЯТЬ = 'нонограмма';
const ТЁМНАЯ = '#151c2e', СИНЯЯ = '#296DF4', КРАСНАЯ = '#dc2626';
const ФОН1 = '#eef2f7', ФОН2 = '#e2e8f1';
const ЧИСЛО = {b: 1, size: 9, align: 'center', valign: 'middle', color: ТЁМНАЯ};
const ПОГАСЛО = {b: 0, color: '#a3adbd'};

let игра = null;    /* {лист, имя, h, w, решение[], сейчас[] (0 пусто, 1 закрашено, 2 крестик), строки[[]], столбцы[[]], секунд, конец, подсказок, ошибки[]} */
let сНачала = 0, тик = null;

/* --- задачи ---------------------------------------------------------------- */
/* В списке задачи идут по номерам: название картинки — это ответ, его видно только после решения. */
function подписьЗадачи(i, решено){
  const к = КАРТИНКИ[i], номер = КАРТИНКИ.slice(0, i + 1).filter(x => x[1] === к[1]).length;
  return (к[1] === 'Разминка' ? 'Разминка 5×5' : к[1]) + ' · №' + номер + (решено && решено[к[0]] != null ? ' — ' + к[0] + ' ✓' : '');
}
const СЛУЧАЙНЫЕ = ['Случайная 10×10', 'Случайная 15×15'];
const размер = рисунок => рисунок.split('/')[0].length + '×' + рисунок.split('/').length;
function свои(){ return хранилище.взять('свои', []) || []; }
function всеЗадачи(){
  const р = хранилище.взять('решено', {}) || {};
  return КАРТИНКИ.map((к, i) => подписьЗадачи(i, р)).concat(СЛУЧАЙНЫЕ, свои().map(с => 'Свой · ' + с.имя + ' (' + размер(с.рисунок) + ')'));
}
function найтиЗадачу(подпись){
  const основа = String(подпись || '').split(' — ')[0];
  const i = КАРТИНКИ.findIndex((к, j) => подписьЗадачи(j) === основа);
  if(i >= 0) return {подпись: основа, имя: КАРТИНКИ[i][0], рисунок: КАРТИНКИ[i][2], ключ: КАРТИНКИ[i][0]};
  const сл = СЛУЧАЙНЫЕ.indexOf(основа);
  if(сл >= 0){ const n = сл ? 15 : 10; return {подпись: основа, имя: 'случайная картинка', рисунок: случайныйРисунок(n), ключ: null}; }
  const с = свои().find(x => основа === 'Свой · ' + x.имя + ' (' + размер(x.рисунок) + ')');
  return с ? {подпись: 'Свой рисунок', имя: с.имя, рисунок: с.рисунок, ключ: null} : null;
}

/* --- решатель по строкам ---------------------------------------------------- */
const блоки = линия => { const out = []; let n = 0; for(const x of линия){ if(x === 1) n++; else if(n){ out.push(n); n = 0; } } if(n) out.push(n); return out; };
/* Какие клетки строки следуют из подсказки п и уже известного (−1 — неизвестно, 0 — пусто, 1 — закрашено):
   перебираем все расстановки блоков с памятью и смотрим, что общего у подходящих. null — противоречие. */
function решитьЛинию(п, л){
  const n = л.length, k = п.length, мем = new Map();
  function можно(i, j){
    const ключ = i * 64 + j;
    if(мем.has(ключ)) return мем.get(ключ);
    let ок = false;
    if(j === k){ ок = true; for(let x = i; x < n; x++) if(л[x] === 1){ ок = false; break; } }
    else {
      if(i < n && л[i] !== 1 && можно(i + 1, j)) ок = true;
      if(!ок && блокВстаёт(i, j) && можно(Math.min(n, i + п[j] + 1), j + 1)) ок = true;
    }
    мем.set(ключ, ок); return ок;
  }
  function блокВстаёт(i, j){
    const e = i + п[j];
    if(e > n) return false;
    for(let x = i; x < e; x++) if(л[x] === 0) return false;
    return e === n || л[e] !== 1;
  }
  if(!можно(0, 0)) return null;
  const может1 = new Array(n).fill(false), может0 = new Array(n).fill(false), был = new Set();
  const стек = [[0, 0]];
  while(стек.length){
    const [i, j] = стек.pop(), ключ = i * 64 + j;
    if(был.has(ключ)) continue; был.add(ключ);
    if(j === k){ for(let x = i; x < n; x++) может0[x] = true; continue; }
    if(i < n && л[i] !== 1 && можно(i + 1, j)){ может0[i] = true; стек.push([i + 1, j]); }
    if(блокВстаёт(i, j) && можно(Math.min(n, i + п[j] + 1), j + 1)){
      const e = i + п[j];
      for(let x = i; x < e; x++) может1[x] = true;
      if(e < n) может0[e] = true;
      стек.push([Math.min(n, e + 1), j + 1]);
    }
  }
  return л.map((v, x) => может1[x] && может0[x] ? -1 : может1[x] ? 1 : 0);
}
/* Решить всё поле логикой. Возвращает сетку с −1 там, где логика бессильна (или null — противоречие). */
function решитьПоле(строки, столбцы, h, w, нач){
  const g = нач ? нач.slice() : new Array(h * w).fill(-1);
  let менялось = true;
  while(менялось){
    менялось = false;
    for(let r = 0; r < h; r++){
      const л = g.slice(r * w, r * w + w), н = решитьЛинию(строки[r], л);
      if(!н) return null;
      for(let c = 0; c < w; c++) if(л[c] === -1 && н[c] !== -1){ g[r * w + c] = н[c]; менялось = true; }
    }
    for(let c = 0; c < w; c++){
      const л = []; for(let r = 0; r < h; r++) л.push(g[r * w + c]);
      const н = решитьЛинию(столбцы[c], л);
      if(!н) return null;
      for(let r = 0; r < h; r++) if(л[r] === -1 && н[r] !== -1){ g[r * w + c] = н[r]; менялось = true; }
    }
  }
  return g;
}
function разобрать(рисунок){
  const ряды = рисунок.split('/'), h = ряды.length, w = ряды[0].length;
  const решение = []; for(const р of ряды) for(const ch of р) решение.push(ch === '#' ? 1 : 0);
  const строки = [], столбцы = [];
  for(let r = 0; r < h; r++) строки.push(блоки(решение.slice(r * w, r * w + w)));
  for(let c = 0; c < w; c++){ const л = []; for(let r = 0; r < h; r++) л.push(решение[r * w + c]); столбцы.push(блоки(л)); }
  return {h, w, решение, строки, столбцы};
}
function однозначна(з){
  const g = решитьПоле(з.строки, з.столбцы, з.h, з.w);
  return g ? g.filter(x => x === -1).length : -1;
}
/* Случайная картинка: пятна (шум, сглаженный «большинством соседей»), и только такие,
   что решаются логикой однозначно. */
function случайныйРисунок(n){
  for(let попытка = 0; попытка < 400; попытка++){
    let g = []; for(let i = 0; i < n * n; i++) g.push(Math.random() < 0.55 ? 1 : 0);
    for(let проход = 0; проход < 2; проход++){
      const н = g.slice();
      for(let r = 0; r < n; r++) for(let c = 0; c < n; c++){
        let s = 0, всего = 0;
        for(let dr = -1; dr <= 1; dr++) for(let dc = -1; dc <= 1; dc++){
          const rr = r + dr, cc = c + dc; if(rr < 0 || cc < 0 || rr >= n || cc >= n) continue; всего++; s += g[rr * n + cc];
        }
        н[r * n + c] = s * 2 > всего ? 1 : s * 2 < всего ? 0 : g[r * n + c];
      }
      g = н;
    }
    const доля = g.reduce((a, b) => a + b, 0) / (n * n);
    if(доля < 0.35 || доля > 0.7) continue;
    const рисунок = []; for(let r = 0; r < n; r++) рисунок.push(g.slice(r * n, r * n + n).map(x => x ? '#' : '.').join(''));
    const з = разобрать(рисунок.join('/'));
    if(однозначна(з) === 0) return рисунок.join('/');
  }
  return КАРТИНКИ[3][2];
}

/* --- раскладка на листе ----------------------------------------------------- */
const высШапки = () => Math.max(1, ...игра.столбцы.map(x => Math.max(1, x.length)));
const ширБока = () => Math.max(1, ...игра.строки.map(x => Math.max(1, x.length)));
const ГР = () => Р0 + высШапки(), ГС = () => С0 + ширБока();
const N = () => игра.h * игра.w;
function прошло(){ return игра && !игра.конец && сНачала ? Math.floor((Date.now() - сНачала) / 1000) : (игра ? игра.секунд || 0 : 0); }
function сохранить(){ лист(игра.лист).запомнить(ПАМЯТЬ, Object.assign({}, игра, {секунд: прошло()})); }
const строкаРешена = r => { const л = []; for(let c = 0; c < игра.w; c++) л.push(игра.сейчас[r * игра.w + c] === 1 ? 1 : 0); return блоки(л).join(' ') === игра.строки[r].join(' '); };
const столбецРешён = c => { const л = []; for(let r = 0; r < игра.h; r++) л.push(игра.сейчас[r * игра.w + c] === 1 ? 1 : 0); return блоки(л).join(' ') === игра.столбцы[c].join(' '); };

function рамкаКлетки(r, c){
  const тон = (край, пятёрка) => край || пятёрка ? {вид: 'средняя', цвет: ТЁМНАЯ} : {вид: 'тонкая', цвет: '#c5ccd8'};
  return {в: тон(r === 0, r % 5 === 0), н: тон(r === игра.h - 1, (r + 1) % 5 === 0),
          л: тон(c === 0, c % 5 === 0), п: тон(c === игра.w - 1, (c + 1) % 5 === 0)};
}
function нарисоватьКлетку(i, сРамкой){
  const r = Math.floor(i / игра.w), c = i % игра.w, к = клетка(ГР() + r, ГС() + c), v = игра.сейчас[i];
  const ошибка = игра.ошибки && игра.ошибки.includes(i);
  const ст = {align: 'center', valign: 'middle', size: 9, b: 0};
  if(сРамкой) ст.гр = рамкаКлетки(r, c);
  if(v === 1){ к.значение = ''; Object.assign(ст, {fill: ошибка ? КРАСНАЯ : игра.конец === 'решено' ? СИНЯЯ : ТЁМНАЯ, color: null}); }
  else if(v === 2){ к.значение = '✕'; Object.assign(ст, {fill: ошибка ? '#fecaca' : null, color: ошибка ? КРАСНАЯ : '#9aa4b5'}); }
  else { к.значение = ''; Object.assign(ст, {fill: null, color: null}); }
  к.стиль = ст;
}
function числаСтроки(r){
  const п = игра.строки[r], шир = ширБока(), гасим = строкаРешена(r), фон = r % 2 ? ФОН2 : ФОН1;
  for(let j = 0; j < шир; j++){
    const к = клетка(ГР() + r, С0 + j), x = j - (шир - п.length);
    к.значение = x >= 0 ? п[x] : (п.length === 0 && j === шир - 1 ? 0 : '');
    к.стиль = Object.assign({}, ЧИСЛО, {fill: фон}, гасим ? ПОГАСЛО : {});
  }
}
function числаСтолбца(c){
  const п = игра.столбцы[c], выс = высШапки(), гасим = столбецРешён(c), фон = c % 2 ? ФОН2 : ФОН1;
  for(let j = 0; j < выс; j++){
    const к = клетка(Р0 + j, ГС() + c), x = j - (выс - п.length);
    к.значение = x >= 0 ? п[x] : (п.length === 0 && j === выс - 1 ? 0 : '');
    к.стиль = Object.assign({}, ЧИСЛО, {fill: фон}, гасим ? ПОГАСЛО : {});
  }
}
const названиеЗадачи = () => игра.подпись + (/\d×\d/.test(игра.подпись) ? '' : ' · ' + игра.w + '×' + игра.h);
function шапка(){
