/* --- ходы ----------------------------------------------------------------- */
function итог(изменённые){
  const ряды = new Set(), столбцы = new Set();
  if(игра.ошибки && игра.ошибки.length){ for(const i of игра.ошибки) изменённые.add(i); игра.ошибки = []; }
  for(const i of изменённые){ нарисоватьКлетку(i); ряды.add(Math.floor(i / игра.w)); столбцы.add(i % игра.w); }
  for(const r of ряды) числаСтроки(r);
  for(const c of столбцы) числаСтолбца(c);
  /* решено, когда закрашены ровно нужные клетки (крестики не важны) */
  if(игра.сейчас.every((v, i) => (v === 1) === (игра.решение[i] === 1))){
    игра.секунд = прошло(); игра.конец = 'решено'; часы(false);
    for(let i = 0; i < N(); i++) if(игра.сейчас[i] === 2) игра.сейчас[i] = 0;
    нарисоватьВсё(); сохранить(); показатьСчёт();
    let слово = 'Решено за ' + ВРЕМЯ(игра.секунд) + (игра.подсказок ? ' (подсказок: ' + игра.подсказок + ')' : '') + ' — это «' + игра.имя + '».';
    if(игра.ключ){
      const р = хранилище.взять('решено', {}) || {}, было = р[игра.ключ];
      if(было == null || игра.секунд < было){ р[игра.ключ] = игра.секунд; хранилище.положить('решено', р); if(было != null) слово += ' Новый рекорд!'; }
      показатьРешённые();
      const все = всеЗадачи(); панель.список('задача', все); панель.поле('задача', все.find(x => x.startsWith(игра.подпись + ' — ')) || игра.подпись);
    }
    панель.сообщение(слово);
    return;
  }
  шапка(); сохранить(); показатьСчёт();
}
/* Что делает щелчок: в режиме «закрашивает» — пусто/крестик → закрашено, закрашено → пусто;
   в режиме «крестик» — наоборот. Для протянутой области берётся первая клетка. */
function цель(v, режим){ return режим === 'крестик' ? (v === 2 ? 0 : 2) : (v === 1 ? 0 : 1); }
function поставить(клетки, режим){
  if(!клетки.length) return;
  const к = цель(игра.сейчас[клетки[0]], режим), изм = new Set();
  for(const i of клетки) if(игра.сейчас[i] !== к){ игра.сейчас[i] = к; изм.add(i); }
  итог(изм);
}
function клеткиПоля(п){
  if(!игра || игра.конец || !п || !п.адрес || п.лист !== игра.лист) return [];
  const обл = String(п.выделение || п.адрес).split(':');
  const разбор = а => { const m = /^([A-Z]+)(\d+)$/.exec(а); if(!m) return null; let c = 0; for(const ch of m[1]) c = c * 26 + ch.charCodeAt(0) - 64; return {r: +m[2] - 1, c: c - 1}; };
  const а = разбор(обл[0]), б = разбор(обл[1] || обл[0]);
  if(!а || !б) return [];
  const r1 = Math.min(а.r, б.r) - ГР(), r2 = Math.max(а.r, б.r) - ГР(), c1 = Math.min(а.c, б.c) - ГС(), c2 = Math.max(а.c, б.c) - ГС();
  if(r1 < 0 || c1 < 0 || r2 >= игра.h || c2 >= игра.w) return [];
  /* первой — та, с которой начали тянуть (курсор) */
  const кур = {r: п.строка - 1 - ГР(), c: п.столбец - 1 - ГС()}, out = [];
  if(кур.r >= r1 && кур.r <= r2 && кур.c >= c1 && кур.c <= c2) out.push(кур.r * игра.w + кур.c);
  for(let r = r1; r <= r2; r++) for(let c = c1; c <= c2; c++){ const i = r * игра.w + c; if(!out.includes(i)) out.push(i); }
  return out;
}

