function Подсказка(){
  if(!игра){ панель.сообщение('Сначала начните задачу.'); return; }
  if(игра.конец) return;
  const ош = неверные();
  if(ош.length){
    игра.ошибки = ош; for(const i of ош) нарисоватьКлетку(i); сохранить();
    панель.сообщение('Сначала ошибки: ' + ош.length + ' (отмечены красным). Подсказка исходит из верно отмеченных клеток.');
    return;
  }
  /* известное: закрашенное — 1, крестики — 0; ищем строку или столбец, где из подсказки следует новое */
  const g = игра.сейчас.map(v => v === 1 ? 1 : v === 2 ? 0 : -1);
  const линии = [];
  for(let r = 0; r < игра.h; r++) линии.push({вид: 'строка', n: r, п: игра.строки[r], клетки: Array.from({length: игра.w}, (_, c) => r * игра.w + c)});
  for(let c = 0; c < игра.w; c++) линии.push({вид: 'столбец', n: c, п: игра.столбцы[c], клетки: Array.from({length: игра.h}, (_, r) => r * игра.w + c)});
  let лучшая = null;
  for(const л of линии){
    const было = л.клетки.map(i => g[i]), стало = решитьЛинию(л.п, было);
    if(!стало) continue;
    const новые = л.клетки.filter((i, x) => было[x] === -1 && стало[x] !== -1).map(i => ({i, v: стало[л.клетки.indexOf(i)]}));
    if(!новые.length) continue;
    const закрасить = новые.filter(x => x.v === 1);
    const оценка = закрасить.length * 2 + новые.length;
    if(!лучшая || оценка > лучшая.оценка) лучшая = {л, новые, закрасить, оценка};
  }
  if(!лучшая){ панель.сообщение('Здесь логика по одной строке не помогает — посмотрите на пересечения.'); return; }
  const {л, новые, закрасить} = лучшая;
  const ход = (закрасить[0] || новые[0]);
  игра.сейчас[ход.i] = ход.v === 1 ? 1 : 2;
  игра.подсказок = (игра.подсказок || 0) + 1;
  const где = л.вид === 'строка' ? 'Строка ' + (л.n + 1) : 'Столбец ' + БУКВА(ГС() + л.n);
  const числа = л.п.length ? л.п.join(' ') : '0';
  панель.сообщение(где + ', числа «' + числа + '»: клетка ' + имяКлетки(ход.i)
    + (ход.v === 1 ? ' закрашена при любой расстановке блоков — закрасил её.' : ' пуста при любой расстановке блоков — поставил крестик.')
    + (новые.length > 1 ? ' В этой линии следует ещё ' + (новые.length - 1) + ' — попробуйте найти сами.' : ''));
  итог(new Set([ход.i]));
}
