/* Свой рисунок: закрашенные (или заполненные) клетки выделенной области — это и есть картинка. */
async function СделатьЗадачу(){
  const в = книга.выделение;
  if(!в || !в.область){ панель.сообщение('Выделите область с рисунком.'); return; }
  const h0 = в.r2 - в.r1 + 1, w0 = в.c2 - в.c1 + 1;
  if(h0 < 3 || w0 < 3 || h0 > 25 || w0 > 25){ панель.сообщение('Выделите рисунок от 3×3 до 25×25 клеток (сейчас ' + w0 + '×' + h0 + ').'); return; }
  /* Выделение уже в снимке книги (плагин объявил «читает: выделение») — читаем его синхронно.
     Сначала заливку, потом значения. Заливку пустых клеток приложение в снимок пока не кладёт,
     поэтому надёжный способ — вписать в клетки рисунка что-нибудь; заливка — запасной. */
  const g = [];
  for(let r = 0; r < h0; r++) for(let c = 0; c < w0; c++){
    const r0 = в.r1 - 1 + r, c0 = в.c1 - 1 + c;
    let есть = false;
    try {
      const цв = Api.GetActiveSheet().GetRange(АДРЕС(r0, c0)).GetFillColor();
      const hex = цв && цв.hex ? цв.hex.toLowerCase() : '';
      есть = !!hex && hex !== '#ffffff';
    } catch(e){}
    if(!есть){
      let v = null;
      try { v = клетка(r0, c0).значение; } catch(e){}
      есть = v !== null && v !== undefined && v !== '' && v !== 0 && v !== '0' && v !== false;
    }
    g.push(есть ? 1 : 0);
  }
  /* поля без рисунка по краям обрезаем */
  let r1 = 0, r2 = h0 - 1, c1 = 0, c2 = w0 - 1;
  const рядПуст = r => g.slice(r * w0, r * w0 + w0).every(x => !x), стлбПуст = c => { for(let r = r1; r <= r2; r++) if(g[r * w0 + c]) return false; return true; };
  while(r1 <= r2 && рядПуст(r1)) r1++;
  while(r2 >= r1 && рядПуст(r2)) r2--;
  if(r1 > r2){ панель.сообщение('В выделенной области нет рисунка: впишите в клетки рисунка что-нибудь — например, 1.'); return; }
  while(стлбПуст(c1)) c1++;
  while(стлбПуст(c2)) c2--;
  const рисунок = [];
  for(let r = r1; r <= r2; r++){ let s = ''; for(let c = c1; c <= c2; c++) s += g[r * w0 + c] ? '#' : '.'; рисунок.push(s); }
  const з = разобрать(рисунок.join('/'));
  const неясно = однозначна(з);
  if(неясно > 0){
    const сетка = решитьПоле(з.строки, з.столбцы, з.h, з.w);
    const ряды = []; for(let r = 0; r < з.h; r++) if(сетка.slice(r * з.w, r * з.w + з.w).includes(-1)) ряды.push(r + 1);
    панель.сообщение('По этому рисунку задача решается неоднозначно: ' + неясно + ' клеток логика не определяет (строки рисунка ' + ряды.slice(0, 8).join(', ') + (ряды.length > 8 ? '…' : '') + '). Добавьте или уберите пару клеток там и попробуйте снова.');
    return;
  }
  const п = параметры({});
  let имя = String(п.имяСвоей || '').trim() || 'Мой рисунок';
  const список = свои().filter(x => x.имя !== имя);
  список.push({имя, рисунок: рисунок.join('/')});
  while(список.length > 40) список.shift();
  хранилище.положить('свои', список);
  const все = всеЗадачи();
  панель.список('задача', все);
  панель.поле('задача', 'Свой · ' + имя + ' (' + размер(рисунок.join('/')) + ')');
  панель.сообщение('Готово: «' + имя + '» ' + з.w + '×' + з.h + ' решается однозначно. Перейдите на пустой лист и нажмите «Начать» — задача уже выбрана в списке.');
}
function УдалитьСвои(){
  хранилище.положить('свои', []);
  панель.список('задача', всеЗадачи());
  панель.сообщение('Свои рисунки удалены из списка.');
}
